// ===========================================================================
// Visibility Probe — run once for all items.
// Reads active queries (from "Get active queries") joined to their entity
// (from "Get tracked entities"), probes each enabled platform, and returns one
// item per (query, platform) shaped exactly like a visibility_checks row.
// ===========================================================================

// --- Platform config: adding/removing a platform is a config change here. ----
const PLATFORMS = [
  { platform: 'google',             keyEnv: 'SERPAPI_KEY',        via: 'serpapi' },
  { platform: 'google_ai_overview', keyEnv: 'SERPAPI_KEY',        via: 'serpapi' }, // derived from same SerpAPI call
  { platform: 'perplexity',         keyEnv: 'PERPLEXITY_API_KEY', via: 'perplexity' },
  { platform: 'chatgpt',            keyEnv: 'OPENAI_API_KEY',     via: 'openai' },
  { platform: 'gemini',             keyEnv: 'GEMINI_API_KEY',     via: 'gemini' },
  { platform: 'claude',             keyEnv: 'ANTHROPIC_API_KEY',  via: 'anthropic' },
];

const http = this.helpers.httpRequest;

// --- Small helpers -----------------------------------------------------------
function normDomain(d) {
  if (!d) return '';
  return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();
}
function hostOf(url) {
  try { return normDomain(new URL(url).host); } catch { return normDomain(url); }
}
function urlMatchesDomain(url, domain) {
  if (!url || !domain) return false;
  const h = hostOf(url);
  return h === domain || h.endsWith('.' + domain);
}
function textIncludes(text, needle) {
  if (!text || !needle) return false;
  return String(text).toLowerCase().includes(String(needle).toLowerCase());
}
function nameMatches(text, name) {
  if (!text || !name) return false;
  if (textIncludes(text, name)) return true;
  // also match the distinctive leading tokens of a long brand name
  const lead = String(name).split(/\s+/).slice(0, 2).join(' ');
  return lead.length >= 4 ? textIncludes(text, lead) : false;
}
function collectUrls(obj, acc = [], depth = 0) {
  if (!obj || depth > 6) return acc;
  if (typeof obj === 'string') {
    const m = obj.match(/https?:\/\/[^\s"'<>)\]]+/g);
    if (m) for (const u of m) acc.push(u);
    return acc;
  }
  if (Array.isArray(obj)) { for (const v of obj) collectUrls(v, acc, depth + 1); return acc; }
  if (typeof obj === 'object') { for (const k of Object.keys(obj)) collectUrls(obj[k], acc, depth + 1); }
  return acc;
}
function baseRow(queryId, platform, extra) {
  return Object.assign({
    query_id: queryId,
    platform,
    mentioned: false,
    cited: false,
    rank: null,
    snippet: null,
    source_urls: [],
    raw_response: null,
  }, extra || {});
}

// --- Load entities and build an id -> entity map -----------------------------
const entityItems = $('Get tracked entities').all();
const entityById = {};
for (const it of entityItems) {
  const e = it.json || {};
  if (e.id) entityById[e.id] = e;
}

const queryItems = $('Get active queries').all();

// --- Per-platform probes. Each returns a partial row (the base is merged). ---
async function probeSerpApi(apiKey, entity, queryText) {
  const data = await http({
    method: 'GET',
    url: 'https://serpapi.com/search.json',
    qs: {
      engine: 'google',
      q: queryText,
      api_key: apiKey,
      hl: 'en',
      gl: 'in',
      num: 20,
    },
    json: true,
  });

  const domain = normDomain(entity.domain);
  const name = entity.name || '';

  // google (organic)
  const organic = Array.isArray(data.organic_results) ? data.organic_results : [];
  let hit = null;
  for (const r of organic) {
    const link = r.link || r.displayed_link || '';
    if ((domain && (urlMatchesDomain(link, domain) || textIncludes(r.displayed_link || '', domain))) ||
        (name && nameMatches(r.title || '', name))) { hit = r; break; }
  }
  const google = baseRow(null, 'google', {
    mentioned: Boolean(hit),
    cited: Boolean(hit),
    rank: hit ? (hit.position ?? null) : null,
    snippet: hit ? (hit.snippet || hit.title || null) : null,
    source_urls: hit && hit.link ? [hit.link] : [],
    raw_response: { engine: 'google', organic_count: organic.length, hit: hit || null },
  });

  // google_ai_overview (AI overview block, if present)
  const ai = data.ai_overview || data.answer_box || null;
  let aiMentioned = false, aiCited = false, aiUrls = [], aiSnippet = null;
  if (ai) {
    const aiText = JSON.stringify(ai);
    aiMentioned = (domain && textIncludes(aiText, domain)) || (name && nameMatches(aiText, name));
    const refs = collectUrls(ai);
    aiUrls = refs.filter((u) => urlMatchesDomain(u, domain));
    aiCited = aiUrls.length > 0;
    if (Array.isArray(ai.text_blocks) && ai.text_blocks[0]) {
      aiSnippet = ai.text_blocks[0].snippet || ai.text_blocks[0].text || null;
    }
  }
  const aiOverview = baseRow(null, 'google_ai_overview', {
    mentioned: Boolean(aiMentioned),
    cited: Boolean(aiCited),
    snippet: aiSnippet,
    source_urls: aiUrls,
    raw_response: ai ? { engine: 'google_ai_overview', present: true } : { engine: 'google_ai_overview', present: false },
  });

  return { google, google_ai_overview: aiOverview };
}

async function probePerplexity(apiKey, entity, queryText) {
  const data = await http({
    method: 'POST',
    url: 'https://api.perplexity.ai/chat/completions',
    headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
    body: {
      model: 'sonar',
      messages: [{ role: 'user', content: queryText }],
    },
    json: true,
  });
  const content = data?.choices?.[0]?.message?.content || '';
  const citations = data.citations || data.search_results || [];
  const citationUrls = (Array.isArray(citations) ? citations : []).map((c) => (typeof c === 'string' ? c : (c.url || c.link || ''))).filter(Boolean);
  return parseAnswer(entity, content, citationUrls, { engine: 'perplexity' });
}

async function probeOpenAI(apiKey, entity, queryText) {
  const data = await http({
    method: 'POST',
    url: 'https://api.openai.com/v1/responses',
    headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
    body: {
      model: 'gpt-4o-mini',
      tools: [{ type: 'web_search_preview' }],
      input: queryText,
    },
    json: true,
  });
  const text = data.output_text || collectText(data.output);
  const urls = collectUrls(data.output || data);
  return parseAnswer(entity, text, urls, { engine: 'chatgpt' });
}

async function probeGemini(apiKey, entity, queryText) {
  const data = await http({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent',
    qs: { key: apiKey },
    headers: { 'Content-Type': 'application/json' },
    body: {
      contents: [{ role: 'user', parts: [{ text: queryText }] }],
      tools: [{ google_search: {} }],
    },
    json: true,
  });
  const cand = data?.candidates?.[0];
  const parts = cand?.content?.parts || [];
  const text = parts.map((p) => p.text || '').join(' ');
  const chunks = cand?.groundingMetadata?.groundingChunks || [];
  const urls = chunks.map((c) => c?.web?.uri).filter(Boolean);
  return parseAnswer(entity, text, urls.length ? urls : collectUrls(data), { engine: 'gemini' });
}

async function probeAnthropic(apiKey, entity, queryText) {
  const data = await http({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json',
    },
    body: {
      model: 'claude-3-5-haiku-latest',
      max_tokens: 1024,
      messages: [{ role: 'user', content: queryText }],
      tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 5 }],
    },
    json: true,
  });
  const blocks = Array.isArray(data.content) ? data.content : [];
  const text = blocks.filter((b) => b.type === 'text').map((b) => b.text || '').join(' ');
  const urls = collectUrls(data.content || data);
  return parseAnswer(entity, text, urls, { engine: 'claude' });
}

function collectText(output) {
  if (!output) return '';
  try {
    return JSON.stringify(output).match(/"text":"((?:[^"\\]|\\.)*)"/g)?.map((m) => m).join(' ') || '';
  } catch { return ''; }
}

// Shared parser for the AI-answer platforms (perplexity/chatgpt/gemini/claude).
function parseAnswer(entity, answerText, urls, rawMeta) {
  const domain = normDomain(entity.domain);
  const name = entity.name || '';
  const uniqueUrls = Array.from(new Set((urls || []).filter(Boolean)));
  const citedUrls = uniqueUrls.filter((u) => urlMatchesDomain(u, domain));
  const mentioned = (domain && (textIncludes(answerText, domain) || citedUrls.length > 0)) ||
                    (name && nameMatches(answerText, name));
  const snippet = answerText ? String(answerText).slice(0, 500) : null;
  return {
    mentioned: Boolean(mentioned),
    cited: citedUrls.length > 0,
    source_urls: citedUrls.length ? citedUrls : uniqueUrls.slice(0, 10),
    snippet,
    raw_response: Object.assign({}, rawMeta, { answer_chars: answerText ? answerText.length : 0, citation_count: uniqueUrls.length }),
  };
}

// --- Main loop ---------------------------------------------------------------
const out = [];
for (const qItem of queryItems) {
  const q = qItem.json || {};
  const entity = entityById[q.entity_id] || { name: null, domain: null };

  for (const cfg of PLATFORMS) {
    const apiKey = $env[cfg.keyEnv];
    if (!apiKey) {
      console.log('[visibility-probe] skipping ' + cfg.platform + ' for query ' + q.id + ' — ' + cfg.keyEnv + ' not set');
      continue;
    }
    try {
      if (cfg.via === 'serpapi') {
        // One SerpAPI call yields both google and google_ai_overview rows.
        // Compute once (on the 'google' pass) and cache on the query item.
        if (cfg.platform === 'google') {
          const r = await probeSerpApi(apiKey, entity, q.query_text);
          qItem.__serp = r;
          out.push(baseRow(q.id, 'google', r.google));
        } else if (cfg.platform === 'google_ai_overview') {
          const r = qItem.__serp || (await probeSerpApi(apiKey, entity, q.query_text));
          out.push(baseRow(q.id, 'google_ai_overview', r.google_ai_overview));
        }
      } else {
        let partial;
        if (cfg.via === 'perplexity') partial = await probePerplexity(apiKey, entity, q.query_text);
        else if (cfg.via === 'openai') partial = await probeOpenAI(apiKey, entity, q.query_text);
        else if (cfg.via === 'gemini') partial = await probeGemini(apiKey, entity, q.query_text);
        else if (cfg.via === 'anthropic') partial = await probeAnthropic(apiKey, entity, q.query_text);
        out.push(baseRow(q.id, cfg.platform, partial));
      }
    } catch (err) {
      console.log('[visibility-probe] ' + cfg.platform + ' failed for query ' + q.id + ': ' + (err && err.message));
      out.push(baseRow(q.id, cfg.platform, {
        mentioned: false,
        cited: false,
        raw_response: { error: String(err && err.message || err), platform: cfg.platform },
      }));
    }
  }
}

return out.map((json) => ({ json }));
